                // Act
                var actual = systemUnderTest.DeepClone();

                // Assert
                actual.AsTest().Must().BeEqualTo(systemUnderTest);
                actual.AsTest().Must().NotBeSameReferenceAs(systemUnderTest);

                if (systemUnderTest.FiscalYearScheme == null)
                {
                    actual.FiscalYearScheme.AsTest().Must().BeNull();
                }
                else if (!actual.FiscalYearScheme.GetType().IsValueType)
                {
                    // When the declared type is a reference type, we still have to check the runtime type.
                    // The object could be a boxed value type, which will fail this asseration because
                    // a deep clone of a value type object is the same object.
                    actual.FiscalYearScheme.AsTest().Must().NotBeSameReferenceAs(systemUnderTest.FiscalYearScheme);
                }

                if (systemUnderTest.WeeksPerQuarter == null)
                {
                    actual.WeeksPerQuarter.AsTest().Must().BeNull();
                }
                else if (!actual.WeeksPerQuarter.GetType().IsValueType)
                {
                    // When the declared type is a reference type, we still have to check the runtime type.
                    // The object could be a boxed value type, which will fail this asseration because
                    // a deep clone of a value type object is the same object.
                    actual.WeeksPerQuarter.AsTest().Must().NotBeSameReferenceAs(systemUnderTest.WeeksPerQuarter);
                }
            }

